### Service Template

```xiom
use xiom.micro::{Service, HealthCheck, Config};

pub type UserService = {
  db: Database,
  config: Config,
  metrics: Metrics,
}

impl Service for UserService {
  fn name(self: &UserService) -> Str { return "user-service"; }

  fn init(config: Config) -> Result<UserService, Error> {
    let db = Database::connect(&config.database_url)?;
    let metrics = Metrics::new("user-service")?;
    return Ok(UserService{ db: db, config: config, metrics: metrics });
  }

  fn serve(self: &UserService) -> Result<(), Error> {
    let server = http::Server::new();

    // Service discovery registration
    discovery::register(self.name(), self.config.port)?;

    // Health check
    server.get("/health", |_| HealthCheck::ok());

    // API routes
    server.get("/users/{id}", |req| self.get_user(req));
    server.post("/users", |req| self.create_user(req));

    // Metrics endpoint
    server.get("/metrics", |_| self.metrics.to_prometheus());

    server.listen(self.config.port)
  }
}
```

### Resilience Patterns

```xiom
// Circuit Breaker
pub type CircuitBreaker = {
  failure_count: Int;
  threshold: Int;
  state: CircuitState,  // Closed, Open, HalfOpen
  last_failure: Timestamp,
}

impl CircuitBreaker {
  fn call[T](self: &mut CircuitBreaker, f: fn() -> Result[T, Error]) -> Result[T, Error] {
    match self.state {
      CircuitState::Open => {
        if time::now() - self.last_failure > self.timeout {
          self.state = CircuitState::HalfOpen;
        } else {
          return Err(Error::CircuitOpen);
        }
      },
      _ => {},
    }

    match f() {
      Ok(value) => {
        self.state = CircuitState::Closed;
        self.failure_count = 0;
        Ok(value)
      },
      Err(e) => {
        self.failure_count = self.failure_count + 1;
        if self.failure_count >= self.threshold {
          self.state = CircuitState::Open;
          self.last_failure = time::now();
        }
        Err(e)
      },
    }
  }
}

// Retry with backoff
fn call_with_retry[T](f: fn() -> Result[T, Error], max: Int) -> Result[T, Error] {
  for attempt in 0..max {
    match f() {
      Ok(v) => return Ok(v),
      Err(e) => {
        os.sleep(2u64.pow(attempt) * 100);  // Exponential backoff
      },
    }
  }
  Err(Error::MaxRetries)
}
```

### Observability

```xiom
// Structured logging
log::info("user_created", {
  user_id: user.id,
  email: user.email,
  timestamp: time::now(),
});

// Metrics
metrics.counter("http_requests_total").increment();
metrics.histogram("http_request_duration_ms").observe(duration_ms);

// Distributed tracing
let span = trace::start_span("create_user");
span.set_attribute("user_id", user_id);
// ... work ...
span.end();
```

### Service Communication

```xiom
// Sync (HTTP/gRPC): request-response
let user = user_service_client.get_user(id)?;

// Async (message queue): fire-and-forget
queue.publish("order.created", OrderCreatedEvent{ order_id: id })?;

// Event-driven: subscribe and react
queue.subscribe("order.created", |event| {
  send_confirmation_email(event.user_id, event.order_id);
  update_inventory(event.items);
});
```

